package com.orderflow.delivery.controller;import com.orderflow.delivery.correlation.DeliveryRequestAttributes;import com.orderflow.delivery.dto.*;import com.orderflow.delivery.service.*;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import java.util.UUID;import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/delivery/agents/me")public class DeliveryAgentController{private final DeliveryAssignmentService assignment;private final DeliveryQueryService query;private final DeliveryCommandService commands;public DeliveryAgentController(DeliveryAssignmentService a,DeliveryQueryService q,DeliveryCommandService c){assignment=a;query=q;commands=c;}
 @PutMapping("/availability")public AgentResponse availability(@Valid @RequestBody AvailabilityRequest body,JwtAuthenticationToken auth,HttpServletRequest request){UUID user=UUID.fromString(auth.getToken().getSubject());assignment.availability(user,body.availability(),correlation(request));return query.agent(user);}@GetMapping public AgentResponse me(JwtAuthenticationToken a){return query.agent(UUID.fromString(a.getToken().getSubject()));}
 @GetMapping("/deliveries")public PageResponse<DeliveryResponse> deliveries(JwtAuthenticationToken a,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return query.agentDeliveries(UUID.fromString(a.getToken().getSubject()),page,size);}@GetMapping("/deliveries/{id}")public DeliveryResponse delivery(@PathVariable UUID id,JwtAuthenticationToken a){return query.agentDelivery(UUID.fromString(a.getToken().getSubject()),id);}
 @PostMapping("/deliveries/{id}/pickup")public DeliveryResponse pickup(@PathVariable UUID id,JwtAuthenticationToken a,HttpServletRequest r){return query.agentDelivery(UUID.fromString(a.getToken().getSubject()),commands.pickup(UUID.fromString(a.getToken().getSubject()),id,correlation(r)).getId());}
 @PostMapping("/deliveries/{id}/out-for-delivery")public DeliveryResponse out(@PathVariable UUID id,JwtAuthenticationToken a,HttpServletRequest r){UUID u=UUID.fromString(a.getToken().getSubject());commands.outForDelivery(u,id,correlation(r));return query.agentDelivery(u,id);}
 @PostMapping("/deliveries/{id}/delivered")public DeliveryResponse delivered(@PathVariable UUID id,JwtAuthenticationToken a,HttpServletRequest r){UUID u=UUID.fromString(a.getToken().getSubject());commands.delivered(u,id,correlation(r));return query.agentDelivery(u,id);}
 @PostMapping("/deliveries/{id}/failed")public DeliveryResponse failed(@PathVariable UUID id,@Valid @RequestBody FailureRequest b,JwtAuthenticationToken a,HttpServletRequest r){UUID u=UUID.fromString(a.getToken().getSubject());commands.failed(u,id,b.failureCode(),correlation(r));return query.agentDelivery(u,id);}
 private String correlation(HttpServletRequest r){return(String)r.getAttribute(DeliveryRequestAttributes.CORRELATION_ID);}}
